function mutateDrawioCell(source, id, mutate, label) { const cell = parseDrawio(source).cells.find(({attributes: item}) => item.get('id') === id); assert.ok(cell, `${label} fixture cell`); const changed = mutate(cell.raw); assert.notEqual(changed, cell.raw, `${label} mutation applies`); return replaceOnce(source, cell.raw, changed, label); }
