function mutateSvgText(source, predicate, mutate, label) { const element = parseSvg(source).elements.find(({name, ...rest}) => name === 'text' && predicate(rest)); assert.ok(element, `${label} fixture text`); const value = source.slice(element.openEnd, element.closeIndex); const changed = mutate(value); assert.notEqual(changed, value, `${label} mutation applies`); return `${source.slice(0, element.openEnd)}${changed}${source.slice(element.closeIndex)}`; }
function frontMatterFixture(metadata) { return Object.entries(metadata).flatMap(([key, value]) => Array.isArray(value) ? value.length ? [`${key}:`, ...value.map((item) => `  - ${item}`)] : [`${key}: []`] : [`${key}: ${value}`]).join('\n'); }
