test('STY-10 helper contracts reject metadata, wrapper, table, ownership and recovery mutations', () => {
  const headings = `${EXPECTED_HEADINGS.map((heading) => heading === '可迁移经验' ? `## ${heading}\n${MIGRATION_HEADINGS.map((item) => `### ${item}`).join('\n')}` : `## ${heading}`).join('\n')}\n[生产中的微前端案例](/cases/micro-frontends-single-spa)只能有限类比独立交付的扩展边界，不等同于进程隔离的后端插件。`;
  const article = `---\n${frontMatterFixture(EXACT_METADATA)}\n---\n${WRAPPERS.map(exactWrapper).join('\n')}\n${headings}\n插件注册表保存插件标识、制品摘要和状态，注册表不执行订单业务。供应链验证器检查来源、签名、摘要和撤销，通过验证不证明插件业务逻辑正确。策略与权限引擎授予最小数据、网络、凭证和资源范围，插件声明需求不决定授权。发布控制器执行验证、预热、灰度、排空和卸载，它不替订单域决定业务补偿。订单微内核宿主拥有订单流程、权威状态、提交和补偿，插件不拥有订单状态机。受控调用网关执行能力解析、协议协商、最小数据投影、幂等键和短期凭证，不取得订单业务决策权。补偿队列只承载通知类工作，不接受税费、支付或库存正确性结果的默认跳过。税费插件、支付插件、库存插件、通知插件每个插件只实现一个被批准的扩展能力。\n未知能力必须拒绝，不能静默接受。没有安全相交范围时拒绝激活，不允许声明自动扩大授权。\n| 维度 | 插件声明 | 宿主/平台门禁 | 不满足时 |\n| --- | --- | --- | --- |\n${GOVERNANCE_ROWS.map((row) => `| ${row.join(' | ')} |`).join('\n')}\n\n| 故障类别 | 检测 | 自动响应 | 停止条件 | 人工所有者 |\n| --- | --- | --- | --- | --- |\n${FAILURE_ROWS.map((row) => `| ${row.join(' | ')} |`).join('\n')}\n\n订单宿主到达扩展点。调用网关向控制面解析绑定。宿主生成最小数据投影：订单 ID、地区、应税项目和合同版本。网关加入操作 ID、幂等键、期限、deadline 和短期凭证。插件返回版本化结果。网关校验响应结构、大小。宿主根据业务失败策略处理。控制面只接收健康与策略信号。超时后结果未知先查询权威结果，不能盲目重放。\n任何阶段失败停止推进并恢复上一批准绑定。回滚只改变新请求绑定，不会撤销已经产生的外部效果。\n插件不得不直连订单数据库，不互相调用或组成隐藏业务流程。进程外执行只提供进程故障边界，不自动形成安全沙箱。不为假想需求预建扩展点。\n收集真实变化和实现差异。在宿主内提取一个合同。固定业务所有权。引入清单、注册表。独立交付或第三方风险成立时，再迁移为进程外 RPC 插件。建立签名、最小权限、配额、灰度、排空、回滚和人工处置。`;
  assertExactMetadata(article); assertArticleHeadings(article); assertWrappers(article); assertOwnership(article); assertGovernance(article); assertInvocationFailureAndLifecycle(article); assertNarrativeBoundaries(article);
  for (const key of Object.keys(EXACT_METADATA)) { const deleted = removeFrontMatterField(article, key); assert.notEqual(deleted, article, `${key} deletion applies`); assert.throws(() => assertExactMetadata(deleted), assert.AssertionError, `${key} deletion rejected`); assert.throws(() => assertExactMetadata(changeFrontMatterField(article, key)), assert.AssertionError, `${key} changed rejected`); }
  for (const heading of [...EXPECTED_HEADINGS, ...MIGRATION_HEADINGS]) { const token = `##${MIGRATION_HEADINGS.includes(heading) ? '#' : ''} ${heading}`; assert.throws(() => assertArticleHeadings(replaceOnce(article, token, '', `${heading} deletion`)), assert.AssertionError, `${heading} deletion rejected`); assert.throws(() => assertArticleHeadings(replaceOnce(article, token, `${token}（变更）`, `${heading} changed`)), assert.AssertionError, `${heading} changed-value rejected`); }
  for (const label of WRAPPERS) { for (const [attribute, changed] of [['role="region"', 'role="table"'], ['tabIndex={0}', 'tabIndex={-1}'], ['onKeyDown={handleHorizontalArrowKey}', 'onKeyDown={undefined}']]) { assert.throws(() => assertWrappers(replaceOnce(article, exactWrapper(label), replaceOnce(exactWrapper(label), attribute, '', `${label} ${attribute} deletion`), `${label} ${attribute} deletion`)), assert.AssertionError, `${label} ${attribute} deletion rejected`); assert.throws(() => assertWrappers(replaceOnce(article, exactWrapper(label), replaceOnce(exactWrapper(label), attribute, changed, `${label} ${attribute} change`), `${label} ${attribute} change`)), assert.AssertionError, `${label} ${attribute} value rejected`); } assert.throws(() => assertWrappers(replaceOnce(article, exactWrapper(label), replaceOnce(exactWrapper(label), 'aria-label=', 'aria-labelX=', `${label} aria deletion`), `${label} aria deletion`)), assert.AssertionError, `${label} aria deletion rejected`); assert.throws(() => assertWrappers(replaceOnce(article, `aria-label="${label}"`, `aria-label="${label}（变更）"`, `${label} changed aria`)), assert.AssertionError, `${label} aria value rejected`); }
  for (const row of GOVERNANCE_ROWS) { const exact = `| ${row.join(' | ')} |`; assert.throws(() => assertGovernance(replaceOnce(article, `${exact}\n`, '', `${row[0]} deletion`)), assert.AssertionError, `${row[0]} row deletion rejected`); for (let index = 0; index < row.length; index += 1) { const deleted = [...row]; deleted[index] = ''; const changed = [...row]; changed[index] = '错误的合同值'; assert.throws(() => assertGovernance(replaceOnce(article, exact, `| ${deleted.join(' | ')} |`, `${row[0]} cell deletion`)), assert.AssertionError, `${row[0]} cell ${index} deletion rejected`); assert.throws(() => assertGovernance(replaceOnce(article, exact, `| ${changed.join(' | ')} |`, `${row[0]} changed`)), assert.AssertionError, `${row[0]} cell ${index} changed rejected`); } }
  const first = `| ${GOVERNANCE_ROWS[0].join(' | ')} |`; const second = `| ${GOVERNANCE_ROWS[1].join(' | ')} |`; assert.throws(() => assertGovernance(article.replace(first, '__SWAP__').replace(second, first).replace('__SWAP__', second)), assert.AssertionError, 'governance row swap rejected');
  for (const [from, to, label] of [['插件声明需求不决定授权', '插件声明需求就是授权', 'declaration/authorization conflation'], ['未知能力必须拒绝，不能静默接受', '未知能力可以静默接受', 'unknown capability silent acceptance'], ['缩小授权；无法运行则拒绝', '扩大授权并继续运行', 'permission widening'], ['没有安全相交范围时拒绝激活', '没有安全相交范围时强制适配', 'forced adapter']]) assert.throws(() => assertGovernance(replaceOnce(article, from, to, label)), assert.AssertionError, `${label} rejected`);
  for (const row of FAILURE_ROWS) { const exact = `| ${row.join(' | ')} |`; assert.throws(() => assertInvocationFailureAndLifecycle(replaceOnce(article, `${exact}\n`, '', `${row[0]} deletion`)), assert.AssertionError, `${row[0]} failure deletion rejected`); for (let index = 0; index < row.length; index += 1) { const deleted = [...row]; deleted[index] = ''; const changed = [...row]; changed[index] = '错误故障语义'; assert.throws(() => assertInvocationFailureAndLifecycle(replaceOnce(article, exact, `| ${deleted.join(' | ')} |`, `${row[0]} failure deletion`)), assert.AssertionError, `${row[0]} failure cell ${index} deletion rejected`); assert.throws(() => assertInvocationFailureAndLifecycle(replaceOnce(article, exact, `| ${changed.join(' | ')} |`, `${row[0]} changed`)), assert.AssertionError, `${row[0]} failure cell ${index} changed rejected`); } }
  for (const unsafe of ['无限重试', '税费失败开放', '通知失败关闭', '超时后盲目重放支付外部效果', '人工所有者待定', '原地热替换在途调用', '回滚撤销已发生外部效果']) assert.throws(() => assertInvocationFailureAndLifecycle(`${article}\n${unsafe}`), assert.AssertionError, `${unsafe} rejected`);
  for (const unsafe of ['插件可以直连订单数据库', '插件之间可以互相调用', '插件可以自行扩大权限', '进程隔离就是安全沙箱', '插件可组成隐藏业务流程', '插件可以为假想需求预建扩展点']) assert.throws(() => assertNarrativeBoundaries(`${article}\n${unsafe}`), assert.AssertionError, `${unsafe} rejected`);
});

test('STY-10 source fixture rejects deletion, rights, role, primary, and boundary mutations', () => {
  const inventory = readFileSync(SOURCE_INVENTORY, 'utf8');
  const remoteIds = SOURCE_IDS.slice(0, -1); const ledger = {sources: [...remoteIds.map((id) => ({id, canonical_locator: REMOTE_SOURCES[id].canonical_locator, transport_locator: REMOTE_SOURCES[id].transport_locator, version: REMOTE_SOURCES[id].version, title: REMOTE_SOURCES[id].title, license: REMOTE_SOURCES[id].license, license_family_id: REMOTE_SOURCES[id].license_family_id, usage_boundary: REMOTE_SOURCES[id].usage_boundary, allowed_evidence_roles: REMOTE_SOURCES[id].roles})), {id: SOURCE_IDS.at(-1), canonical_locator: ORIGINAL_SOURCE.canonical_locator, license: ORIGINAL_SOURCE.license, copyright_policy: ORIGINAL_SOURCE.copyright_policy, license_family_id: ORIGINAL_SOURCE.license_family_id, usage_boundary: ORIGINAL_SOURCE.usage_boundary}], documents: {[ARTICLE]: {citations: [...remoteIds.map((id) => ({source_id: id, roles: REMOTE_SOURCES[id].roles, manifest_primary: REMOTE_SOURCES[id].primary, usage_mode: 'facts-summary'})), {source_id: SOURCE_IDS.at(-1), roles: ['illustration'], manifest_primary: false, usage_mode: 'original-illustration'}]}}}; assertSourceContracts(ledger, inventory);
  for (const id of SOURCE_IDS) { const changed = structuredClone(ledger); changed.sources = changed.sources.filter((entry) => entry.id !== id); assert.throws(() => assertSourceContracts(changed, inventory), assert.AssertionError, `${id} deletion rejected`); }
  for (const id of SOURCE_IDS) { const changed = structuredClone(ledger); const source = changed.sources.find((entry) => entry.id === id); assert.ok(source, `${id} boundary mutation source`); const originalBoundary = source.usage_boundary; source.usage_boundary = `${source.usage_boundary} Widened to support copied text and diagrams.`; assert.notEqual(source.usage_boundary, originalBoundary, `${id} usage-boundary mutation applies`); assert.throws(() => assertSourceContracts(changed, inventory), assert.AssertionError, `${id} usage-boundary widening rejected independently`); }
  const coordinatedLedger = structuredClone(ledger); const coordinatedSource = coordinatedLedger.sources.find((entry) => entry.id === 'src-vscode-extension-host'); assert.ok(coordinatedSource, 'coordinated VS Code source'); const originalBoundary = coordinatedSource.usage_boundary; coordinatedSource.usage_boundary = 'Supports unrestricted copied text, diagrams, code, trademarks, page structure, product guarantees, and architecture conclusions.'; assert.notEqual(coordinatedSource.usage_boundary, originalBoundary, 'coordinated ledger widening applies'); const coordinatedInventory = replaceOnce(inventory, REMOTE_SOURCES['src-vscode-extension-host'].inventory_policy, 'Copied text, diagrams, code, trademarks, and page structure allowed without limitation', 'coordinated inventory widening'); assert.throws(() => assertSourceContracts(coordinatedLedger, coordinatedInventory), assert.AssertionError, 'coordinated ledger/inventory widening rejected');
  const rights = structuredClone(ledger); rights.sources[0].license = 'MIT'; assert.throws(() => assertSourceContracts(rights, inventory), assert.AssertionError, 'rights mutation rejected'); const role = structuredClone(ledger); role.sources[1].allowed_evidence_roles = ['learning']; role.documents[ARTICLE].citations[1].roles = ['learning']; assert.throws(() => assertSourceContracts(role, inventory), assert.AssertionError, 'role mutation rejected'); const primary = structuredClone(ledger); primary.documents[ARTICLE].citations[0].manifest_primary = false; primary.documents[ARTICLE].citations[1].manifest_primary = true; assert.throws(() => assertSourceContracts(primary, inventory), assert.AssertionError, 'primary mutation rejected');
});

