test('STY-10 SVG cascade and real terminal helpers reject drift', () => {
  const svg = '<svg><style>#host > .edge[data-edge-id="x"] { stroke:#0F766E !important; font-size:45px; } .marker-role > .marker-shape { fill:#0F766E; }</style><g id="host" stroke="#DC2626"><path class="edge" data-edge-id="x" style="stroke:#000000" d="M 0 0 L 30 0"/></g><defs><marker class="marker-role"><path class="marker-shape" d="M 0 0 L 1 1"/></marker></defs></svg>'; const parsed = parseSvg(svg); const edge = parsed.edges.find(({attributes: item}) => item.get('data-edge-id') === 'x'); const markerShape = parsed.elements.find(({attributes: item}) => item.get('class') === 'marker-shape'); assert.equal(svgPresentationValue(svg, edge, 'stroke'), '#0F766E', 'important ID/attribute child selector wins'); assert.equal(svgPresentationValue(svg, edge, 'font-size'), '45px', 'effective SVG font size'); assert.equal(svgPresentationValue(svg, markerShape, 'fill'), '#0F766E', 'descendant selector and inheritance tree'); assert.equal(decodeXmlText('&amp;&lt;&gt;&quot;&apos;'), '&<>"\'', 'named XML entities decode'); assert.deepEqual(parsePathPoints(edge.attributes.get('d')), [{x: 0, y: 0}, {x: 30, y: 0}], 'real SVG path points'); const node = {attributes: new Map([['id', 'node']]), geometry: new Map([['x', '0'], ['y', '0'], ['width', '100'], ['height', '100']])}; const edgeCell = {attributes: new Map([['id', 'edge'], ['style', 'exitX=1;exitY=0.5;exitDx=0;exitDy=0;exitPerimeter=1']])}; assert.deepEqual(terminalPoint(node, edgeCell, 'exit'), {x: 100, y: 50}, 'real normalized terminal'); assert.throws(() => terminalPoint(node, {attributes: new Map([['id', 'edge'], ['style', 'exitX=0.7;exitY=0.5;exitDx=0;exitDy=0;exitPerimeter=1']])}, 'exit'), assert.AssertionError, 'non-perimeter terminal rejected'); const box = glyphBox({x: 100, y: 100, text: '订单宿主', fontSize: 45, anchor: 'middle'}); assert.ok(box.left < box.right && box.top < box.bottom, 'glyph box has visible geometry'); const labelRoute = [{x: 0, y: 0}, {x: 100, y: 0}]; const clearGlyph = {left: 40, right: 60, top: 24, bottom: 28}; assertRouteGlyphClearance(labelRoute, clearGlyph, 'synthetic glyph'); const overlappingGlyph = {...clearGlyph, top: -2, bottom: 2}; assert.notDeepEqual(overlappingGlyph, clearGlyph, 'glyph-overlap mutation applies'); assert.throws(() => assertRouteGlyphClearance(labelRoute, overlappingGlyph, 'synthetic glyph overlap'), assert.AssertionError, 'visible glyph overlap mutation rejected'); assert.deepEqual(alphaCompose({red: 0, green: 0, blue: 0, alpha: 0}, {red: 255, green: 255, blue: 255, alpha: .5}), {red: 255, green: 255, blue: 255, alpha: .5}, 'alpha composition uses source-over'); const flatSvg = '<svg><g id="glyph-parent"><rect data-node-id="node" x="0" y="0" width="20" height="20"/><path data-edge-id="flat-edge" d="M 0 0 L 20 0"/><text data-edge-id="flat-edge" x="0" y="30">label</text></g></svg>'; assertFlattenedSvg(parseSvg(flatSvg).elements); for (const [label, mutated] of [['node', flatSvg.replace('<rect ', '<rect transform="translate(1 0)" ')], ['path', flatSvg.replace('<path ', '<path transform="translate(1 0)" ')], ['text', flatSvg.replace('<text ', '<text transform="translate(1 0)" ')], ['ancestor group', flatSvg.replace('<g id="glyph-parent"', '<g id="glyph-parent" transform="translate(1 0)"')]]) { assert.notEqual(mutated, flatSvg, `${label} transform mutation applies`); assert.throws(() => assertFlattenedSvg(parseSvg(mutated).elements), assert.AssertionError, `${label} transform rejected`); } const markerSource = '<svg><path data-edge-id="marker-edge" marker-end="url(#arrow)" d="M 0 60 L 120 60"/><defs><marker id="arrow" markerUnits="userSpaceOnUse" viewBox="0 0 12 12" markerWidth="24" markerHeight="24" refX="12" refY="6" orient="auto"><path d="M 0 0 L 12 6 L 0 12 Z"/></marker></defs></svg>'; const markerSvg = parseSvg(markerSource); const markerEdge = markerSvg.edges.find(({attributes: item}) => item.get('data-edge-id') === 'marker-edge'); const marker = markerBounds(markerSource, markerSvg.elements, markerEdge, parsePathPoints(markerEdge.attributes.get('d'))); assert.deepEqual(marker, {left: 96, right: 120, top: 48, bottom: 72}, 'user-space marker viewBox and path envelope'); const collidingNode = {left: 121, right: 130, top: 50, bottom: 70}; const shiftedSource = markerSource.replace('refX="12"', 'refX="0"'); const shiftedSvg = parseSvg(shiftedSource); const shiftedEdge = shiftedSvg.edges.find(({attributes: item}) => item.get('data-edge-id') === 'marker-edge'); const shifted = markerBounds(shiftedSource, shiftedSvg.elements, shiftedEdge, parsePathPoints(shiftedEdge.attributes.get('d'))); assert.throws(() => assert.equal(overlaps(shifted, collidingNode), false, 'marker misses foreign node'), assert.AssertionError, 'marker geometry mutation collides with node'); const asymmetricSource = markerSource.replace('markerWidth="24"', 'markerWidth="48"'); assert.notEqual(asymmetricSource, markerSource, 'asymmetric meet marker mutation applies'); const unconstrainedAsymmetric = markerEnvelope({x: 120, y: 60}, {x: 0, y: 60}, {width: 48, height: 24, refX: 12, refY: 6, viewBox: [0, 0, 12, 12], pathBounds: {left: 0, right: 12, top: 0, bottom: 12}, preserveAspectRatio: 'none'}); assert.ok(overlaps(unconstrainedAsymmetric, {left: 73, right: 95, top: 50, bottom: 70}), 'unconstrained asymmetric marker would collide'); for (const [label, mutated] of [['markerUnits', markerSource.replace('userSpaceOnUse', 'strokeWidth')], ['viewBox', markerSource.replace('0 0 12 12', '0 0 0 12')], ['marker width', markerSource.replace('markerWidth="24"', 'markerWidth="0"')], ['marker height', markerSource.replace('markerHeight="24"', 'markerHeight="0"')], ['marker meet aspect', asymmetricSource], ['marker reference', markerSource.replace('refX="12"', 'refX="13"')], ['marker orient', markerSource.replace('orient="auto"', 'orient="90"')], ['marker preserveAspectRatio', markerSource.replace('orient="auto"', 'orient="auto" preserveAspectRatio="xMaxYMax slice"')], ['marker path', markerSource.replace('M 0 0 L 12 6 L 0 12 Z', 'M -1 0 L 12 6 L 0 12 Z')]]) { const changed = parseSvg(mutated); const changedEdge = changed.edges.find(({attributes: item}) => item.get('data-edge-id') === 'marker-edge'); assert.throws(() => markerBounds(mutated, changed.elements, changedEdge, parsePathPoints(changedEdge.attributes.get('d'))), assert.AssertionError, `${label} mutation rejected`); } assert.throws(() => assertNoLaterPaintMask([{x: 0, y: 0}, {x: 30, y: 0}], [{left: 10, right: 20, top: -1, bottom: 1, alpha: 1}]), assert.AssertionError, 'later opaque paint mask rejected');
});

test('STY-10 diagram inventory helpers reject terminal, geometry, crossing, marker, and paint mutations', () => {
  const left = {attributes: new Map([['id', 'node-left']]), geometry: new Map([['x', '0'], ['y', '0'], ['width', '120'], ['height', '120']])}; const right = {attributes: new Map([['id', 'node-right']]), geometry: new Map([['x', '400'], ['y', '0'], ['width', '120'], ['height', '120']])}; const nodes = new Map([['node-left', left], ['node-right', right]]); const raw = '<mxCell id="edge" edge="1" source="node-left" target="node-right" style="semanticRole=invocation;strokeColor=#0F766E;strokeWidth=3;dashPattern=;exitX=1;exitY=0.5;exitDx=0;exitDy=0;exitPerimeter=1;entryX=0;entryY=0.5;entryDx=0;entryDy=0;entryPerimeter=1;"><mxGeometry relative="1" as="geometry"><Array as="points"><mxPoint x="260" y="60"/></Array></mxGeometry></mxCell>'; const edge = parseDrawio(raw).edges[0]; assert.deepEqual(drawioRoute(edge, nodes), [{x: 120, y: 60}, {x: 260, y: 60}, {x: 400, y: 60}], 'Draw.io route derives endpoints and waypoint'); for (const [label, mutated] of [['port', raw.replace('exitX=1', 'exitX=0.7')], ['waypoint array', raw.replace('<Array as="points"><mxPoint x="260" y="60"/></Array>', '')], ['fallback source point', raw.replace('</Array>', '</Array><mxPoint x="1" y="1" as="sourcePoint"/>')]]) assert.throws(() => drawioRoute(parseDrawio(mutated).edges[0], nodes), assert.AssertionError, `${label} mutation rejected`);
  const throughMiddle = [{x: 0, y: 60}, {x: 400, y: 60}]; const foreignBox = {left: 160, right: 240, top: 20, bottom: 100}; assert.equal(routeBoxDistance(throughMiddle, foreignBox), 0, 'segment through node/region/label middle has zero clearance'); assert.ok(routeBoxDistance([{x: 0, y: 0}, {x: 400, y: 0}], foreignBox) > 0, 'segment clear of rectangle retains distance'); assert.equal(segmentsCross({x: 0, y: 0}, {x: 20, y: 20}, {x: 0, y: 20}, {x: 20, y: 0}), true, 'route crossing measured'); assert.equal(segmentsCross({x: 0, y: 0}, {x: 20, y: 0}, {x: 30, y: 10}, {x: 40, y: 10}), false, 'separated routes do not cross'); assert.equal(partialCollinearOverlap({x: 0, y: 0}, {x: 20, y: 0}, {x: 10, y: 0}, {x: 30, y: 0}), true, 'partial collinear overlap measured'); const shared = {source: 'shared', target: 'left', points: [{x: 0, y: 0}, {x: 20, y: 0}]}; const sibling = {source: 'shared', target: 'right', points: [{x: 0, y: 0}, {x: 0, y: 20}]}; assert.equal(exactSharedTerminalContact(shared, sibling, shared.points[0], shared.points[1], sibling.points[0], sibling.points[1]), true, 'only exact shared terminal is allowed'); const marker = markerEnvelope({x: 120, y: 60}, {x: 0, y: 60}, {width: 24, height: 24, refX: 10, refY: 6, viewBox: [0, 0, 12, 12], pathBounds: {left: 0, right: 12, top: 0, bottom: 12}}); assert.ok(overlaps(marker, {left: 100, right: 150, top: 40, bottom: 80}), 'viewBox-transformed marker envelope captures footprint'); assert.throws(() => assertNoLaterPaintMask([{x: 0, y: 0}, {x: 100, y: 0}], [{left: 40, right: 60, top: -1, bottom: 1, alpha: .2}]), assert.AssertionError, 'translucent later mask rejected');
});

test('STY-10 diagram inventory production mutations reject unsafe topology and visual drift', () => {
  const drawio = file(DRAWIO); const svg = file(SVG); if (!drawio || !svg) return;
  const rejected = (changedDrawio, changedSvg, label) => assert.throws(() => assertDiagram(changedDrawio, changedSvg), assert.AssertionError, `${label} rejected`);
  rejected(mutateDrawioCell(drawio, 'register-manifest', (raw) => raw.replace('exitX=1;', ''), 'missing exit port'), svg, 'missing exit port');
  rejected(mutateDrawioCell(drawio, 'register-manifest', (raw) => raw.replace('exitX=1;', 'exitX=0.7;'), 'changed exit port'), svg, 'changed exit port');
  rejected(mutateDrawioCell(drawio, 'verify-artifact', (raw) => raw.replace(/<Array as="points">[\s\S]*?<\/Array>/u, ''), 'missing waypoint array'), svg, 'missing waypoint array');
  rejected(mutateDrawioCell(drawio, 'verify-artifact', (raw) => raw.replace('</mxGeometry>', '<mxPoint x="1" y="1" as="sourcePoint"/></mxGeometry>'), 'fallback sourcePoint'), svg, 'fallback sourcePoint');
  for (const [id, from, to, label] of [
    ['commit-order', 'source="node-order-microkernel-host"', 'source="node-tax-plugin"', 'plugin/database edge'],
    ['invoke-payment', 'source="node-controlled-invocation-gateway"', 'source="node-tax-plugin"', 'plugin/plugin edge'],
    ['activate-binding', 'source="node-release-controller"', 'source="node-controlled-invocation-gateway"', 'detached control-plane decision'],
    ['invoke-payment', 'target="node-payment-plugin"', 'target="node-compensation-queue"', 'critical failure sent to compensation queue'],
    ['enqueue-notification-compensation', 'target="node-compensation-queue"', 'target="node-order-store"', 'notification failure sent to order abort'],
    ['rollback-binding', 'target="node-order-microkernel-host"', 'target="node-payment-authority"', 'rollback entering an external effect'],
  ]) rejected(mutateDrawioCell(drawio, id, (raw) => raw.replace(from, to), label), svg, label);
  rejected(mutateDrawioCell(drawio, 'legend-edge-control', (raw) => raw.replace('legendRole=control;', 'legendRole=invocation;'), 'legend role drift'), svg, 'legend role drift');
  rejected(drawio, mutateSvgElement(svg, ({name, attributes: item}) => name === 'text' && item.get('data-header-for') === 'node-order-microkernel-host', (open) => open.replace('font-size="45"', 'font-size="42"'), 'changed node font'), 'changed node font');
  rejected(drawio, replaceOnce(svg, '</svg>', '<rect x="600" y="548" width="40" height="4" fill="#FFFFFF"/></svg>', 'opaque label mask'), 'opaque label mask');
  const overlapDrawio = mutateDrawioCell(drawio, 'verify-artifact', (raw) => raw.replace(/<Array as="points">[\s\S]*?<\/Array>/u, '<Array as="points"><mxPoint x="600" y="550"/></Array>'), 'partial edge overlap');
  const overlapSvg = mutateSvgElement(svg, ({name, attributes: item}) => name === 'path' && item.get('data-edge-id') === 'verify-artifact', (open) => open.replace(/d="[^"]+"/u, 'd="M 1140 550 L 600 550 L 1260 550"'), 'partial edge overlap SVG');
  rejected(overlapDrawio, overlapSvg, 'partial edge overlap');
  rejected(drawio, mutateSvgElement(svg, ({name, attributes: item}) => name === 'marker' && item.get('id') === 'arrow-control', (open) => open.replace('refX="12"', 'refX="0"'), 'shifted marker into legend boundary'), 'shifted marker into legend boundary');
  if (svg.includes('data-region-label-for="control-plane"')) {
    rejected(mutateDrawioCell(drawio, 'region-label-plugins', (raw) => raw.replace(REGION_LABELS['plugin-processes'], ''), 'deleted paired plugin-region label'), svg, 'deleted paired plugin-region label');
    rejected(drawio, mutateSvgText(svg, ({attributes: item}) => item.get('data-region-label-for') === 'execution-plane', () => '执行面：插件拥有业务决策权', 'region-label semantic drift'), 'region-label semantic drift');
    rejected(drawio, mutateSvgElement(svg, ({name, attributes: item}) => name === 'text' && item.get('data-region-label-for') === 'plugin-processes', (open) => open.replace(/x="[^"]+"/u, 'x="2250"'), 'plugin-region heading boundary collision'), 'plugin-region heading boundary collision');
    rejected(mutateDrawioCell(drawio, 'note-security-boundary-line-1', (raw) => raw.replace(NOTE_CONTRACTS['note-security-boundary'].lines[0], ''), 'deleted sandbox note'), svg, 'deleted sandbox note');
    rejected(drawio, mutateSvgText(svg, ({attributes: item}) => item.get('data-note-line-for') === 'note-failure-policy-line-1', () => '关键请求失败：写入补偿队列', 'failure-policy semantic drift'), 'failure-policy semantic drift');
    rejected(drawio, mutateSvgElement(svg, ({name, attributes: item}) => name === 'text' && item.get('data-note-line-for') === 'note-security-boundary-line-1', (open) => open.replace(/font-size="[^"]+"/u, 'font-size="42"'), 'note font below 15 CSS pixels'), 'note font below 15 CSS pixels');
    rejected(drawio, mutateSvgElement(svg, ({name, attributes: item}) => name === 'text' && item.get('data-note-line-for') === 'note-security-boundary-line-2', (open) => open.replace(/x="[^"]+"/u, 'x="100"'), 'sandbox note boundary collision'), 'sandbox note boundary collision');
    rejected(drawio, mutateSvgElement(svg, ({name, attributes: item}) => name === 'text' && item.get('data-note-line-for') === 'note-failure-policy-line-2', (open) => open.replace(/y="[^"]+"/u, 'y="2950"'), 'failure note boundary collision'), 'failure note boundary collision');
    rejected(drawio, mutateSvgElement(svg, ({name, attributes: item}) => name === 'text' && item.get('data-edge-id') === 'isolate-plugin', (open) => open.replace(/x="[^"]+"/u, 'x="2330"'), 'isolation label boundary collision'), 'isolation label boundary collision');
  }
});

test('STY-10 article locks exact metadata, semantic contracts, and wrappers', () => { const {source, body} = articleParts(file(ARTICLE)); assertExactMetadata(source); assertArticleHeadings(source); assertWrappers(source); assertOwnership(body); assertGovernance(body); assertInvocationFailureAndLifecycle(body); assertNarrativeBoundaries(body); });
test('STY-10 terminology exceptions lock only the eight current literal records', () => { const source = file(ARTICLE); assertScopedTerminologyExceptions(source); for (const scope of TERMINOLOGY_SCOPES) { const directive = terminologyDirective(scope); assert.throws(() => assertScopedTerminologyExceptions(replaceOnce(source, directive, '', `${scope.match} scoped exception deletion`)), assert.AssertionError, `${scope.match} scoped exception deletion rejected`); assert.throws(() => assertScopedTerminologyExceptions(replaceOnce(source, directive, directive.replace(`match: ${scope.match}`, 'match: unrelated-term'), `${scope.match} scoped exception widening`)), assert.AssertionError, `${scope.match} scoped exception widening rejected`); } });
test('STY-10 source governance, reciprocal relations, and Stage A projection are exact', async () => { assertSourceContracts(JSON.parse(readFileSync('data/source-ledger.json', 'utf8')), readFileSync(SOURCE_INVENTORY, 'utf8')); await assertRelationsAndStageA(); });
test('STY-10 Draw.io/SVG diagram locks dual-plane inventory and physical source terminals', () => { const drawio = file(DRAWIO); const svg = file(SVG); assert.ok(drawio, `${DRAWIO} must exist after implementation`); assert.ok(svg, `${SVG} must exist after implementation`); assertDiagram(drawio, svg); });
